(* Compute amplitudes for two-minus sector and try to find pattern *)

Get["../OnShellBG.m"];

gVal = 1;

(* Two-minus sector: sigma = {-1,-1,+1,...,+1} *)
twoMinusSigma[n_] := Join[{-1, -1}, Table[1, n-2]];

(* Generate kinematic points *)
kinematicSets = {
  {4, {{1, 2}}},  (* n=4, 2 free frequencies: w2,w3 *)
  {5, {{2, 3, 5}}, {1, 2, 3}},   (* n=5 *)
  {6, {{1, 2, 3, 4}}},  (* n=6 *)
  {7, {{1, 2, 3, 4, 5}}}  (* n=7 *)
};

Do[
  Block[{n = k[[1]], fwSet = k[[2 ;;]], sigmas, ks, ws, amp},
   sigmas = twoMinusSigma[n];
   Do[
     Block[{fw},
      (* Use rational numbers *)
      fw = Map[Rationalize, fws];
      {ks, ws} = MakeKinematics[n, fw, sigmas, gVal];
      If[ks === $Failed, Continue[]];

      amp = BGAmplitude[ks, ws, gVal];
      Print["n=", n, " freeW=", fws, " A=", Simplify[amp]];
     ],
     {fws, fwSet}
   ]
  ],
  {k, kinematicSets}
]

